import { mergeWith, isArray } from 'lodash';
import { useMemo } from 'react';
import { useWalletHistoryListInfiniteQuery } from '~/entities/wallet/api/use-wallet-history-list-infinite-query';
import { useWalletSearch } from '~/entities/wallet/lib/use-wallet-search';

export const useMergedHistoryList = () => {
  const { searchParam } = useWalletSearch();
  const { coinId, coinType, walletInsttCd, aliasNm, vouchId, stDt, edDt, text, walletDetailSe } = searchParam;

  const { data, hasNextPage, fetchNextPage, refetch, isLoading } = useWalletHistoryListInfiniteQuery({
    search: {
      coinId,
      coinType,
      walletInsttCd,
      aliasNm,
      vouchId,
      stDt,
      edDt,
      text,
      walletDetailSe,
    },
  });

  const mergedList = useMemo(() => {
    if (!data?.pages) return {};

    const flattenNewList = data.pages.map((page) => page.result.newList).flat();
    return mergeWith({}, ...flattenNewList, (objValue: any, srcValue: any) => {
      if (isArray(objValue)) {
        return objValue.concat(srcValue);
      }
    });
  }, [data?.pages]);

  return {
    mergedList,
    hasNextPage,
    fetchNextPage,
    refetch,
    isLoading,
    isEmpty: !data || Object.keys(mergedList)?.length === 0,
    searchParam,
  };
};
