import { isEqual } from 'lodash-es';
import { memo, useEffect, useRef } from 'react';
import { useWalletSearchParams } from '~/entities/wallet/lib/use-wallet-search-params';
import { WalletHistoryViewType, WalletSearchParams } from '~/entities/wallet/types';

type WalletSearchParamsProviderProps = {
  params?: Partial<Omit<WalletSearchParams, 'viewType'>> & {
    viewType: WalletHistoryViewType;
  };
  children: React.ReactNode;
};

export const WalletSearchParamsProvider = memo(function WalletSearchParamsProvider({
  params,
  children,
}: WalletSearchParamsProviderProps) {
  const { updateSearchParams } = useWalletSearchParams();
  const prevParams = useRef(params);

  useEffect(() => {
    if (params && !isEqual(params, prevParams.current)) {
      const updatedParams = {
        stDt: null,
        edDt: null,
        coinId: null,
        coinType: null,
        walletInsttCd: null,
        aliasNm: null,
        vouchId: null,
        walletDetailSe: null,
        ...params,
      } as const;

      updateSearchParams(updatedParams);
      prevParams.current = params;
    }
  }, [params, updateSearchParams]);

  return <>{children}</>;
});
