import { useErrorBoundary } from '@suspensive/react';
import { InfiniteData, useInfiniteQuery } from '@tanstack/react-query';
import { DEFAULT_HISTORY_PAGE_SIZE, DEFAULT_HISTORY_PAGING } from '~/entities/wallet/api/dtos/constants';
import {
  WalletHistoryListRequestDTO,
  WalletHistoryListResponseDTO,
} from '~/entities/wallet/api/dtos/wallet-history-list';
import { walletApi } from '~/entities/wallet/api/wallet-api';
import { restructureList } from '~/entities/wallet/lib/restructure-list';
import { CBDCAxiosError } from '~/shared/@types/error';
import { InfiniteQueryOptions } from '~/shared/@types/query';
import { queries } from '~/shared/api/query-keys';
import { getGlobalQueryClient } from '~/shared/config/query';
import i18n from '~/shared/i18n/i18n';

export const useWalletHistoryListInfiniteQuery = (
  { paging = DEFAULT_HISTORY_PAGING, search }: WalletHistoryListRequestDTO,
  options?: InfiniteQueryOptions<
    WalletHistoryListResponseDTO,
    CBDCAxiosError,
    InfiniteData<WalletHistoryListResponseDTO>,
    readonly unknown[],
    WalletHistoryListRequestDTO
  >,
) => {
  const { setError } = useErrorBoundary();
  if (!paging || !search) {
    setError(new Error(i18n.t('validation:temporaryErrorOccurred')));
  }

  return useInfiniteQuery<
    WalletHistoryListResponseDTO,
    CBDCAxiosError,
    InfiniteData<WalletHistoryListResponseDTO>,
    readonly unknown[],
    WalletHistoryListRequestDTO
  >({
    queryKey: queries.wallet.walletHistoryList({ paging, search }).queryKey,
    queryFn: ({ pageParam = { paging, search } }) =>
      walletApi.getWalletHistoryList({ paging: pageParam.paging, search: pageParam.search }),
    initialPageParam: { paging, search },
    getNextPageParam: (lastPage) => {
      if (lastPage?.result?.list?.length < DEFAULT_HISTORY_PAGE_SIZE) {
        return undefined;
      }
      return {
        paging: {
          ...paging,
          currentPageNo: (lastPage?.result?.paging.currentPageNo ?? 1) + 1,
        },
        search,
      };
    },
    select: (data) => {
      data.pages?.map((page) => {
        page.result.newList = restructureList(page.result?.list);
      });

      return data;
    },
    gcTime: 0,
    staleTime: 0,
    refetchOnMount: 'always',
    refetchOnWindowFocus: 'always',
    refetchOnReconnect: 'always',
    ...options,
  });
};

export const resetWalletHistoryListInfiniteQuery = () => {
  const queryClient = getGlobalQueryClient();
  queryClient.invalidateQueries({
    queryKey: queries.wallet.walletHistoryList._def,
  });
};
