import { forwardRef } from 'react';
import { Fragment } from 'react/jsx-runtime';
import { WalletNewList } from '~/entities/wallet/api/dtos/wallet-history-list';
import { HistoryItem } from '~/entities/wallet/ui/wallet-history/history-item';

type HistoryListProps = {
  list: WalletNewList;
};

export const HistoryList = forwardRef<HTMLDivElement, HistoryListProps>(function HistoryList({ list: newList }, ref) {
  const flatList = Object.values(newList).flat();

  return (
    <>
      {Object.keys(newList).map((key) => (
        <Fragment key={key}>
          {newList[key].map((item) => {
            const isLastItem = flatList[flatList.length - 1].trnscId === item.trnscId;
            return <HistoryItem item={item} key={item.trnscId} ref={isLastItem ? ref : undefined} />;
          })}
        </Fragment>
      ))}
    </>
  );
});
