import { ErrorBoundary } from '@suspensive/react';
import { QueryErrorResetBoundary } from '@tanstack/react-query';
import { Suspense, memo } from 'react';
import { useSearchParams } from 'react-router-dom';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { useFixScrollViewSafari } from '~/shared/lib/hooks';
import { HistoryListContent } from './history-list-content';

type HistoryListContainerProps = {
  title: string;
};

export const HistoryListContainer = memo(function HistoryListContainer({ title }: HistoryListContainerProps) {
  useFixScrollViewSafari();
  useSetHeaderTitle(title);
  const [searchParams] = useSearchParams();

  return (
    <QueryErrorResetBoundary>
      {({ reset }) => (
        <ErrorBoundary fallback={FallbackErrorMessage} resetKeys={[searchParams.toString()]} onReset={reset}>
          <Suspense fallback={<LoadingSpinner />}>
            <HistoryListContent />
          </Suspense>
        </ErrorBoundary>
      )}
    </QueryErrorResetBoundary>
  );
});
