import { forwardRef } from 'react';
import { useSearchParams } from 'react-router-dom';
import { WalletItemDTO } from '~/entities/wallet/api/dtos/wallet-item';
import { DisplayAmount } from '~/entities/wallet/ui/wallet-history/display-amount';
import { RcppaySttusCd, TrnscTypeCd } from '~/shared/api/dtos/enums';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

type HistoryItemProps = {
  item: WalletItemDTO;
};

export const HistoryItem = forwardRef<HTMLDivElement, HistoryItemProps>(function HistoryItem({ item }, ref) {
  const { navigate } = useNavigate();
  const [searchParams] = useSearchParams();

  const moveToDetail = () => {
    const vouchId = item.vouchId ?? searchParams.get('vouchId') ?? undefined;
    const search = vouchId ? `?vouchId=${encodeURIComponent(vouchId)}` : '';
    navigate(`${PATHS.myWallet.historyDetail}${item.trnscId}${search}`);
  };

  const typeName =
    item.trnscTypeCd === TrnscTypeCd.송금 && item.rcppaySttusCd === RcppaySttusCd.입금코드
      ? '받기'
      : item.walletDetailSeNm;

  return (
    <div className="wallet-detail-history-item" ref={ref} onClick={moveToDetail}>
      <div className="wallet-detail-history-item-top">
        <div className="wallet-detail-history-info-wrapper">
          <span className="wallet-detail-history-date">{item.time}</span>
          <i className="icon-wallet-detail-history-divider"></i>
          <span className="wallet-detail-history-type">{typeName}</span>
        </div>
        <div className="wallet-detail-history-label">{item.title}</div>
      </div>
      <div className="wallet-detail-history-item-bottom">
        <DisplayAmount amount={item.trnscAmt} type={item.rcppaySttusCd} />
      </div>
    </div>
  );
});
