import { useEffect } from 'react';
import { useInView } from 'react-intersection-observer';
import { LoadingSpinner } from '~/widgets/loading/loading-spinner';
import { resetWalletHistoryListInfiniteQuery } from '~/entities/wallet/api/use-wallet-history-list-infinite-query';
import { useMergedHistoryList } from '~/entities/wallet/lib/use-merged-history-list';
import i18n from '~/shared/i18n/i18n';
import { HistoryList } from './history-list';

export const HistoryListContent = () => {
  const [ref, inView] = useInView();
  const { mergedList, hasNextPage, fetchNextPage, isLoading, isEmpty } = useMergedHistoryList();

  useEffect(() => {
    if (hasNextPage && inView) {
      fetchNextPage();
    }
  }, [fetchNextPage, hasNextPage, inView]);

  if (isLoading) {
    return <LoadingSpinner />;
  }

  if (isEmpty) {
    return (
      <section className="wallet-detail-history-container">
        <div className="main-empty-state">
          <p className="empty-text">{i18n.t('validation:noHistoryAvailable')}</p>
        </div>
      </section>
    );
  }

  return (
    <section className="wallet-detail-history-container">
      <HistoryList list={mergedList} ref={ref} />
    </section>
  );
};
